-- 북악산 전체 seed data
-- 원본: 산림청 등산로정보 PMNTN / PMNTN_SPOT
-- 산 코드: 111100101(북악산)
-- 원본 건수: PMNTN 119피처, PMNTN_SPOT 82피처
-- 적재 건수: raw_trail 119건, trail_spot 82건
-- 모든 원본 등산로가 LineString이므로 119건을 그대로 적재한다.
-- 원본 좌표계: ITRF2000 TM Korea Central Belt (EPSG:5186 파라미터)
-- DB 저장 좌표계: EPSG:5179
-- 원본 기준일: 2016-12-31, 수집일: 2026-11-23
--
-- 이 파일은 신규 북악산 seed 최초 실행 전용이다.
-- 산·원천 데이터·네트워크·서비스 영역·태그·지점 매칭을 한 트랜잭션으로 처리한다.
-- 기존 관악산 seed와 Flyway migration은 변경하지 않는다.

BEGIN;

-- 같은 이름의 활성 산이 있으면 기존 참조를 보호하기 위해 중단한다.
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.mountain
        WHERE mountain_nm = '북악산'
          AND use_yn = 'Y'
    ) THEN
        RAISE EXCEPTION '활성 북악산 데이터가 이미 존재합니다. 이 seed는 최초 실행 전용입니다.';
    END IF;
END
$$;

INSERT INTO public.mountain (
    mountain_nm, src_mntn_cd, src_old_mntn_cd, use_yn,
    province_nm, district_nm, address_label, elevation_m, representative_geom
) VALUES (
    '북악산', '111100101', NULL, 'Y',
    '서울특별시', '종로구·성북구',
    '서울특별시 북악산', 342.00,
    ST_Transform(ST_SetSRID(ST_MakePoint(126.97253399, 37.60177137), 4326), 5179)
);

SELECT set_config('orda.seed.mountain_id', mountain_id::text, true)
FROM public.mountain
WHERE mountain_nm = '북악산'
  AND use_yn = 'Y';

